<?php require '../includes/functions.php';$u=guard();check_csrf();try{$name=field('name',100);$phone=field('phone',20);$city=field('city',100);$address=field('address');if(!preg_match('/^[0-9+ ()-]{7,20}$/',$phone))throw new Exception('Enter a valid phone number.');$hash=$u['password'];if(($_POST['new_password']??'')!==''){if(!password_verify($_POST['current_password']??'',$hash))throw new Exception('Current password is incorrect.');if(strlen($_POST['new_password'])<8||strlen($_POST['new_password'])>200)throw new Exception('Use a password of 8–200 characters.');$hash=password_hash($_POST['new_password'],PASSWORD_DEFAULT);}query('UPDATE users SET name=?,phone=?,city=?,address=?,password=? WHERE id=?',[$name,$phone,$city,$address,$hash,$u['id']]);flash('Profile saved.');}catch(Exception $e){flash($e instanceof PDOException?'Unable to save profile.':$e->getMessage(),'error');}go('profile.php');